#!/usr/bin/env python3
"""Validate only the 500 frozen concept groups generated by the ours method."""

from __future__ import annotations

import argparse
import json
from collections import Counter
from pathlib import Path
from typing import Any

import demo_pipeline as pipeline


ROOT = Path(__file__).resolve().parent
DEFAULT_CANDIDATES = ROOT / "runs/demo/data/frozen_candidates.json"
DEFAULT_VALIDATION = ROOT / "runs/demo/data/validation_2024_raw.jsonl"
DEFAULT_OUTPUT = ROOT / "runs/demo/data/evidence_2024_ours_500.json"


def select_ours_candidates(candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:
    ours = [candidate for candidate in candidates if candidate.get("method") == "ours"]
    if len(ours) != 500:
        raise ValueError(f"Expected exactly 500 frozen ours candidates; found {len(ours)}")
    return ours


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Validate only frozen candidates generated by the ours method."
    )
    parser.add_argument("--candidates", type=Path, default=DEFAULT_CANDIDATES)
    parser.add_argument("--manifest", type=Path)
    parser.add_argument("--validation", type=Path, default=DEFAULT_VALIDATION)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--year", type=int, choices=(2024, 2025), default=2024)
    parser.add_argument("--qwen-model", default=pipeline.DEFAULT_QWEN_MODEL)
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Verify and report the 500-candidate selection without loading a model.",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _build_parser().parse_args(argv)
    frozen_candidates, manifest = pipeline.load_and_verify_candidates(
        args.candidates, args.manifest
    )
    candidates = select_ours_candidates(frozen_candidates)
    selected_hash = pipeline.candidate_sha256(candidates)

    print(
        json.dumps(
            {
                "source_candidate_sha256": manifest["candidate_sha256"],
                "selected_candidate_sha256": selected_hash,
                "selected_candidates": len(candidates),
                "method_counts": dict(Counter(item["method"] for item in candidates)),
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    if args.dry_run:
        return 0

    documents = pipeline.read_jsonl(args.validation)
    if not documents:
        raise ValueError(f"Validation input is empty: {args.validation}")

    historical_dois = {
        str(doi).casefold() for doi in manifest.get("historical_dois", [])
    }
    overlap_count = sum(
        bool(document.get("doi"))
        and str(document["doi"]).casefold() in historical_dois
        for document in documents
    )
    validation_documents = [
        document
        for document in documents
        if not document.get("doi")
        or str(document["doi"]).casefold() not in historical_dois
    ]
    if not validation_documents:
        raise ValueError("All validation documents overlap with the historical corpus")

    qwen = pipeline.LocalQwen(args.qwen_model)
    rows = pipeline.validate_candidates(
        candidates, validation_documents, qwen, args.year
    )
    result = {
        "candidate_sha256": selected_hash,
        "source_candidate_sha256": manifest["candidate_sha256"],
        "candidate_method": "ours",
        "candidate_count": len(candidates),
        "validation_year": args.year,
        "review_model": "local_qwen",
        "review_model_path": qwen.model_path,
        "review_prompt_version": pipeline.EVIDENCE_REVIEW_PROMPT_VERSION,
        "review_protocol": (
            "Sentence-only local Qwen classification; model-positive evidence "
            "is counted as support."
        ),
        "validation_documents_before_overlap_exclusion": len(documents),
        "historical_doi_overlap_excluded": overlap_count,
        "validation_documents_searched": len(validation_documents),
        "evidence": rows,
    }
    pipeline.write_json(args.output, result)

    supported_groups = pipeline.extract_ours_supported_groups(
        rows, selected_hash, args.year
    )
    supported_path = args.output.with_name(
        f"{args.output.stem}_supported.jsonl"
    )
    pipeline.write_jsonl(supported_path, supported_groups)

    review_counts = Counter(
        item.get("review_model_label", "missing")
        for row in rows
        for item in row["evidence"]
    )
    print(f"Wrote evidence for {len(rows)} ours candidates to {args.output}")
    print(
        f"Wrote {len(supported_groups)} strictly supported ours groups "
        f"to {supported_path}"
    )
    print(json.dumps(dict(review_counts), ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
